/**
 * Creates a type-safe RPC example with schema-based type checking
 * @param method - The RPC method name (must match a key in RpcSchemas)
 * @param request - The request parameters (typed against the schema)
 * @param response - The response value (typed against the schema)
 * @returns A properly structured example object
 */
export function createExample<TMethod extends keyof typeof RpcSchemas>(
  method: TMethod,
  request: z.input<(typeof RpcSchemas)[TMethod]>["Request"]["params"],
  response: z.input<(typeof RpcSchemas)[TMethod]>["ReturnType"],
): {
  name: string;
  params: readonly [
    {
      name: "Request";
      value: z.input<(typeof RpcSchemas)[TMethod]>["Request"]["params"];
    },
  ];
  result: {
    name: "Response";
    value: z.input<(typeof RpcSchemas)[TMethod]>["ReturnType"];
  };
} {
  return {
    name: `${String(method)} example`,
    params: [
      {
        name: "Request" as const,
        value: request,
      },
    ],
    result: {
      name: "Response" as const,
      value: response,
    },
  } as const;
}
